      <div class="visit-banner"><div><span class="banner-icon" aria-hidden="true">◷</span><div><strong>Next visit · {{ date(client.next_date, { weekday: 'short' }) }} at {{ client.time }}</strong><p>{{ client.frequency }} · {{ client.location }}</p></div></div><span class="badge" :class="client.reminder.startsWith('Confirmed') ? 'green' : ''">{{ client.reminder }}</span></div>
      <nav class="chart-tabs" role="tablist" aria-label="Client chart sections" @keydown="tabKey">
        <button v-for="item in tabs" :id="`chart-tab-${item.id}`" :key="item.id" type="button" role="tab" :aria-selected="tab === item.id" :aria-controls="`chart-panel-${item.id}`" :tabindex="tab === item.id ? 0 : -1" :class="{active: tab === item.id}" data-analytics-id="chart-tab" @click="tab = item.id">{{ item.label }}</button>
      </nav>
      <section :id="`chart-panel-${tab}`" class="chart-panel" role="tabpanel" :aria-labelledby="`chart-tab-${tab}`" tabindex="0">
