          <div class="chart-columns">
            <div class="main-column">
              <article class="panel care-panel"><div class="panel-heading"><div><p class="eyebrow">CARE AT A GLANCE</p><h2>A clear picture of their care</h2></div><span class="badge green">{{ client.plan_status }}</span></div><dl class="care-facts"><div><dt>Assigned provider</dt><dd>{{ client.provider_name }}, {{ client.provider_credential }}</dd></div><div><dt>Visit cadence</dt><dd>{{ client.frequency }}</dd></div><div><dt>Care focus</dt><dd>{{ client.focus }}</dd></div><div><dt>Diagnosis</dt><dd>{{ client.diagnosis }}</dd></div></dl><div v-if="client.supervisor_id" class="supervision-callout"><span aria-hidden="true">✓</span><p><strong>Supervised care</strong>Documentation is reviewed by {{ supervisor?.name }}, {{ supervisor?.credential }}.</p></div></article>
              <article class="panel plan-panel"><div class="panel-heading"><div><p class="eyebrow">TREATMENT PLAN</p><h2>Progress that stays connected to the note</h2></div><button type="button" class="text-button" data-analytics-id="chart-tab" @click="tab = 'plan'">View plan →</button></div><h3>{{ client.focus }}</h3><p>{{ client.goal }}</p><template v-if="client.target"><div class="rating-line"><strong>{{ client.rating }}<small> / 10</small></strong><span>Current objective rating</span><span class="rating-change">+{{ client.rating - client.baseline }} from baseline</span></div><div class="rating-track" role="img" :aria-label="`Objective rating ${client.rating} of 10, baseline ${client.baseline}, target ${client.target}`"><span class="rating-fill" :style="{width: `${client.rating * 10}%`}"></span><span class="rating-target" :style="{left: `${client.target * 10}%`}"></span></div><div class="rating-labels"><span>Baseline {{ client.baseline }}/10</span><span>Target {{ client.target }}/10</span></div><p class="small-copy">Clinician-recorded objective rating · Higher means more consistent use of the skill.</p></template><p v-else class="empty-inline">Treatment goals and ratings are established after the initial assessment.</p><div class="panel-footer">Next plan review <strong>{{ date(client.plan_review_date) }}</strong></div></article>
              <article class="panel"><div class="panel-heading"><div><p class="eyebrow">RECENT ACTIVITY</p><h2>The latest in one place</h2></div></div><ol class="timeline"><li><span class="timeline-dot"></span><div><strong>{{ client.note_status }}</strong><p>{{ client.service }} · {{ date(client.last_date) }}</p><RouterLink :to="noteLink()" data-analytics-id="chart-note-open">Review documentation →</RouterLink></div></li><li><span class="timeline-dot sage-dot"></span><div><strong>{{ client.status === 'INTAKE' ? 'Intake packet available' : 'Treatment plan reviewed' }}</strong><p>{{ client.status === 'INTAKE' ? 'Review the sample intake and consent information.' : 'Goals, objectives and clinician ratings are linked to the chart.' }}</p></div></li><li><span class="timeline-dot gold-dot"></span><div><strong>{{ client.guardian_names.length ? 'Separate guardian access' : 'Client portal connected' }}</strong><p>{{ client.guardian_names.length ? 'Each guardian has an individual account and contact preferences.' : 'Appointments, forms and care-team communication in one place.' }}</p></div></li></ol></article>
